import { touchResidency } from '@projexlight/sdk-data-rights';
// inside sdk-billing.generateInvoice():
await touchResidency({
  person_id: invoice.subject_person_id,
  store_ref: 'billing.invoice',
  owner_sdk: '@projexlight/sdk-billing',
});

import { openRequest, materializePlan } from '@projexlight/sdk-data-rights';
const { request_id } = await openRequest({
  tenant_id, subject_person_id, request_kind: 'access',
  requested_by_persona_id, deadline_at,
});
await materializePlan({ request_id });

// driven by event subscription:
subscribeEvents('consent.receipt.revoked.v1', async (e) => {
  await openRequest({
    tenant_id: e.tenant_id, subject_person_id: e.subject_person_id,
    request_kind: 'erasure',
    requested_by_persona_id: SYSTEM_PERSONA,
  });
});

